import{_ as n,a as t}from"./chunks/dataflow-converter-dialog.CaG_3Yb6.js";import{_ as i,o as r,c as s,a3 as a}from"./chunks/framework.BlfGB29P.js";const k=JSON.parse('{"title":"Datenfluss – Werte, Konvertierung und Berechnung","description":"","frontmatter":{"title":"Datenfluss – Werte, Konvertierung und Berechnung"},"headers":[],"relativePath":"projects/grafik-visual-studio/datenfluss.md","filePath":"projects/grafik-visual-studio/datenfluss.md","lastUpdated":1792852622000}'),d={name:"projects/grafik-visual-studio/datenfluss.md"};function o(g,e,u,l,h,c){return r(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="ha-grafik-–-datenfluss" tabindex="-1">HA Grafik – Datenfluss <a class="header-anchor" href="#ha-grafik-–-datenfluss" aria-label="Permalink to &quot;HA Grafik – Datenfluss&quot;">​</a></h1><p>Ab <strong>0.1.287</strong> lassen sich <strong>alle Widgets</strong> über <strong>WIDGET → In Runtime verstecken</strong> ausblenden. Das Projekt danach speichern. Ein ausgeblendetes Number-Widget kann weiterhin Werte an Math übergeben; eine ausgeblendete MathBox rechnet weiterhin. Die Checkbox deaktiviert keine Wertequelle und funktioniert unabhängig vom Z-Index. Im Editor bleibt alles bearbeitbar.</p><p>Bis Studio <strong>0.1.285</strong> ergänzt: SVG-Line und Wert-Verbindung unterstützen <strong>Linie → Vertikale Startposition</strong>. Rechtwinklige vertikale Linien laufen erst senkrecht, dann auf Zielhöhe nach links oder rechts. Punktgriffe starten nach 6 px Bewegung und verschieben keine Mehrfachauswahl. Angedockte Linien als Ganzes mit <strong>Alt</strong> ziehen. Eine normale SVG-Line mit <strong>Z-Index −100 oder kleiner</strong> bleibt ebenfalls in der Runtime unsichtbar, ohne ihre Werte zu verlieren. Sie kann <strong>Number → Math</strong> verbinden; Anleitung und Nullwert-Beispiel unter <a href="./svg-linebox-math">LineBox Math</a>.</p><p>Ab Studio <strong>0.1.141</strong> enthält die eigene Palette <strong>HA Grafik – Datenfluss</strong> drei Widgets. Alle Berechnungen und Konvertierungen laufen im Browser des jeweiligen Display-Computers. Home Assistant liefert die Entitätswerte; zusätzliche HA-Entitäten sind für die interne Verarbeitung nicht nötig. Die Visualisierung muss dafür geöffnet sein.</p><table tabindex="0"><thead><tr><th>Widget</th><th>Im Editor</th><th>In der Runtime</th></tr></thead><tbody><tr><td><strong>Wert-Verbindung</strong></td><td>Einfache SVG-Linie ohne Animation, mit Richtung vom Start zum Ziel</td><td>Unsichtbar; Werte werden weitergegeben</td></tr><tr><td><strong>Wert-Konverter</strong></td><td>Widget und eigener Dialog mit Radiobuttons, Eingangs-/Ausgangstyp und Vorschau</td><td>Immer unsichtbar; Konvertierung bleibt aktiv</td></tr><tr><td><strong>Wert-Berechnung</strong></td><td>Gleicher Editor wie <a href="./svg-linebox-math">SVG LineBox Math</a>, mit vier Rechnungen und Anschlüssen A–P</td><td>Standardmäßig unsichtbar; alle Rechnungen und Ausgänge bleiben aktiv</td></tr></tbody></table><p>Wert-Verbindung und Wert-Berechnung verwenden intern die bestehenden SVG-Line- und SVG-LineBox-Math-Typen. Dadurch bleiben Andocken, Verschieben, Kopieren, Projektimport/-export und die gemeinsame Rechenlogik erhalten. Bei SVG LineBox Math lässt sich <strong>In Runtime ausblenden</strong> ebenfalls einschalten. Bei Wert-Berechnung kannst du diese Option wieder ausschalten, wenn du das Rechenwidget sehen möchtest.</p><h2 id="eine-quelle-verbinden" tabindex="-1">Eine Quelle verbinden <a class="header-anchor" href="#eine-quelle-verbinden" aria-label="Permalink to &quot;Eine Quelle verbinden&quot;">​</a></h2><p><img src="'+n+'" alt="Einzelner Ausgangspunkt mit Positionsauswahl"></p><p>Seit 0.1.154 bleibt CSS Allgemein auch bei diesen Widgets verpflichtend aktiv; die übrigen CSS-Bereiche sind optional.</p><p>Ab <strong>0.1.143</strong> sind bei neuen Datenfluss-Widgets die optionalen CSS-Bereiche standardmäßig deaktiviert, bei Wert-Berechnung zusätzlich <strong>Darstellung</strong>. Berechnung und Konvertierung bleiben aktiv. Die Bereiche lassen sich bei Bedarf einschalten; deaktivierte CSS-Felder werden nicht exportiert. Neue Wert-Verbindungen haben an beiden Enden keine Pfeilspitzen. Bereits gespeicherte Widgets behalten ihre Einstellungen.</p><ol><li>Schalte bei einem Widget mit Entitäts- oder Vorschauwert unter <strong>Datenfluss</strong> <strong>Ausgangspunkt aktivieren</strong> ein. Wähle mit den Radiobuttons <strong>Oben</strong>, <strong>Unten</strong>, <strong>Rechts</strong> oder <strong>Links</strong> die Mitte der entsprechenden Seite; standardmäßig rechts. Dieser einzelne Ausgang funktioniert unabhängig vom Bereich <strong>Andockpunkte</strong> und ist abschaltbar. Unter <strong>Einstellungen → Ausgangspunkt</strong> stellst du seine eigene Farbe ein. Der Punkt ist nur im Editor sichtbar; die Wertweitergabe bleibt in der Runtime aktiv. Widgets ohne verfügbaren Wert, etwa reine Rahmen, liefern keinen Wert. Bestehende Andockpunkt-Konfigurationen bleiben erhalten; LineBox, LineBox Math und Konverter verwenden weiterhin ihre eigenen Anschlüsse.</li><li>Füge eine <strong>Wert-Verbindung</strong> ein: Start an den Ausgang der Quelle, Ziel an den Eingang des Konverters oder Empfängers. Der Wertfluss folgt immer dieser Richtung, auch ohne sichtbare Pfeilspitzen; Linienanimation ist ausgeschaltet.</li><li>Öffne am Konverter <strong>Konvertierung bearbeiten</strong>, wähle Ein- und Ausgang und aktiviere <strong>Gewählte Ein-/Ausgangs-Dockpunkte aktivieren</strong>. Neue Dockpunkte bleiben bis zur ausdrücklichen Aktivierung aus.</li><li>Wähle die Konvertierung und prüfe die Vorschau. Bei <strong>Number</strong> und <strong>String</strong> im Basic-Set aktiviere unter <strong>Datenfluss</strong> <strong>Eingangspunkt aktivieren</strong>. Bei anderen normalen Empfängern aktiviere <strong>Wert vom Datenfluss übernehmen</strong> und deren Eingangs-Dockpunkt. Number kann alternativ seine bestehende numerische Dockpunktübernahme verwenden; dort werden mehrere Zahlenwerte weiterhin summiert.</li></ol><p>Ein Konverter und die allgemeine Datenflussübernahme erlauben <strong>genau eine Quelle je Eingang</strong>. Mehrere ausgehende Verbindungen dürfen dasselbe Ergebnis an unterschiedliche Empfänger verteilen. Der Konverter summiert keine Texte oder Schaltzustände. LineBox Math behält seine eigene Summierung numerischer Mehrfachbelegungen.</p><h3 id="eingangspunkt-bei-number-und-string" tabindex="-1">Eingangspunkt bei Number und String <a class="header-anchor" href="#eingangspunkt-bei-number-und-string" aria-label="Permalink to &quot;Eingangspunkt bei Number und String&quot;">​</a></h3><p>Ab Studio <strong>0.1.274</strong> bieten beide Basic-Widgets unter <strong>Datenfluss</strong> einen eigenen Eingangspunkt. Wie beim Ausgang wählst du <strong>Oben</strong>, <strong>Unten</strong>, <strong>Rechts</strong> oder <strong>Links</strong>; standardmäßig liegt der Eingang links. Der Eingang funktioniert unabhängig vom Bereich <strong>Andockpunkte</strong>. Mit seiner Aktivierung übernimmt das Widget den Wert der angeschlossenen Quelle im Editor und in der Runtime. Beim Wechsel der Seite wandern bestehende Eingangsverbindungen mit. Ein zusätzlich aktivierter Ausgang kann den übernommenen Wert weitergeben.</p><p>Nach dem Abschalten der Datenflussübernahme zeigt das Widget wieder seinen Entitäts- oder Vorschauwert. Die Datenflusspunkte sind nur im Editor sichtbar.</p><h2 id="konverterdialog" tabindex="-1">Konverterdialog <a class="header-anchor" href="#konverterdialog" aria-label="Permalink to &quot;Konverterdialog&quot;">​</a></h2><p><img src="'+t+'" alt="Konverterdialog mit Radiobuttons und Vorschau für Temperaturtext zu Zahl"></p><table tabindex="0"><thead><tr><th>Konvertierung</th><th>Einstellungen und Ergebnis</th></tr></thead><tbody><tr><td>Zahl → Text</td><td>0–10 Nachkommastellen, Dezimalpunkt oder -komma, optionale Einheit</td></tr><tr><td>Text → Zahl</td><td>Dezimalpunkt/-komma und angehängte Einheit erkennen; Ausgabe als Zahl</td></tr><tr><td>Schaltzustand → Zahl</td><td>Ein → 1, Aus → 0; optional invertieren</td></tr><tr><td>Zahl → Schaltzustand</td><td>Ein bei Wert ≥ Schwellwert, ansonsten Aus; optional invertieren</td></tr><tr><td>Schaltzustand → Text</td><td>Eigene Texte für Ein und Aus; optional invertieren</td></tr><tr><td>Schaltzustand normalisieren</td><td><code>on/off</code>, <code>true/false</code> oder <code>1/0</code> einlesen; Ausgabe als echte Booleans, Zahlen oder <code>on/off</code>-Text</td></tr><tr><td>Zahl skalieren</td><td><code>Wert * Faktor + Offset</code>, optional Zieleinheit; z. B. °C → °F mit Faktor 1,8 und Offset 32</td></tr></tbody></table><p>Groß-/Kleinschreibung und äußere Leerzeichen werden bei Schaltzuständen toleriert. Unbekannte Zustände werden gemeldet. Nur die zum gewählten Modus passenden Einstellungen werden angezeigt. Änderungen werden erst mit <strong>Anwenden</strong> übernommen und unterstützen Rückgängig.</p><h2 id="einheiten-und-fehler" tabindex="-1">Einheiten und Fehler <a class="header-anchor" href="#einheiten-und-fehler" aria-label="Permalink to &quot;Einheiten und Fehler&quot;">​</a></h2><p><code>23,5 °C</code> wird in Zahlenwert <strong>23,5</strong> und Einheit <strong>°C</strong> getrennt. Bei einem reinen Wert wird die HA-Einheit aus <code>unit_of_measurement</code> beziehungsweise die Widget-Einheit übernommen. Fehlt beides, kannst du eine Fallback-Einheit eintragen. Eine bereits im Text vorhandene Einheit hat Vorrang und wird bei Textausgabe nicht doppelt angehängt. <strong>Einheit im Text mit ausgeben</strong> ist optional. Einheitenerkennung allein führt keine Umrechnung durch; dafür wählst du ausdrücklich <strong>Zahl skalieren</strong> mit passendem Faktor, Offset und Ziel.</p><p>Leere Werte, <code>unknown</code>, <code>unavailable</code>, ungültige Zahlen, unbekannte Schaltzustände, inaktive Eingänge, Mehrfachquellen und Rückkopplungen erzeugen einen Fehler. Standardmäßig wird dann kein Wert ausgegeben. <strong>Ersatzwert bei Fehler aktivieren</strong> ist zunächst aus und gibt bei Aktivierung den eingetragenen Ersatztext aus; das ist keine automatische Zahl- oder Boolean-Konvertierung.</p><p>Beispiel: Temperaturanzeige <code>23,5 °C</code> → Konverter <strong>Text → Zahl</strong> → Wert-Berechnung <code>A * 2</code> → Number <strong>47,0</strong>. In der Runtime sind nur Temperaturanzeige und Number sichtbar. Ergebnisse werden intern weitergegeben und nicht automatisch in Home Assistant gespeichert. Ein einfacher Schwellwert hat derzeit keine Hysterese; er wechselt direkt an der Grenze.</p>',23)])])}const p=i(d,[["render",o]]);export{k as __pageData,p as default};
